//returns the customber data or undefined
export async function dwdbfsCustGet(custId) {
   try {
      const custDoc = await firestore().collection('Customers').doc(custId).get();
      return custDoc.data()
   }
   catch (error) { prjAlert(error.message); }
}// end dwdbfsGetCust

