//run a transaction to get the next sequential customer id
//by incrementing Counters.CustId.lastAlloc
//throws error if problem
async function dwdbfsCustGenerateNewId() {
   let currId
   const ctrDocRef = firestore().collection('Counters').doc('CustId')
   await firestore().runTransaction(async trnx => {
      const counterDoc = await trnx.get(ctrDocRef)
      if (!counterDoc.exists) { throw "Unable to access Counters document" }
      if (!counterDoc.data().hasOwnProperty('lastAlloc')) { throw "Unable to access CustId Counter" }
      currId = counterDoc.data().lastAlloc + 1
      await trnx.update(ctrDocRef, { lastAlloc: currId })
   })
   return currId
}// end dwdbfsCustGenerateNewId

//returns true iff successful
//catches and annunciates any errors
export async function dwdbfsCustUpdate(cust) {
   try {
      await firestore().collection('Customers').doc(cust.id).update(cust)
      return true
   }
   catch (err) {
      cmnAlertPopup({ title: 'ERROR dwdbfsCustUpdateProfile', text: err.message })
      return false
   }

}//end dwdbfsCustUpdate

//throws any errors
